/// <summary>
/// Constructor
/// </summary>
/// <param name = "_key">_key</param>
/// <param name = "_value">_value</param>
/// <param name = "_dataType">_dataType</param>
public void new(str _key, str _value, SysApplicationInsightsComplianceDataType _dataType)
{
    key = _key;
    dataType = _dataType;
    super(_value);
}

/// <summary>
/// initialize
/// </summary>
/// <returns>container</returns>
protected container initialize()
{
    return [key, dataType];
}
